-- =============================================================================
-- PROCEDURE 5: OUTPUT parameters with multiple assignments
-- Computes department statistics and returns them via OUTPUT params
-- =============================================================================

CREATE OR REPLACE PROCEDURE public.sp_GetDepartmentStats(
    p_DepartmentID INT,
    INOUT p_EmployeeCount INT,
    INOUT p_TotalSalary DECIMAL(12,2),
    INOUT p_AvgSalary DECIMAL(10,2),
    INOUT p_MinSalary DECIMAL(10,2),
    INOUT p_MaxSalary DECIMAL(10,2),
    INOUT p_BudgetRemaining DECIMAL(12,2)
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_Budget DECIMAL(12,2);
BEGIN
    -- Validate department exists
    IF NOT EXISTS (SELECT 1 FROM public.Departments WHERE DepartmentID = p_DepartmentID) THEN
        p_EmployeeCount := 0;
        p_TotalSalary := 0;
        p_AvgSalary := 0;
        p_MinSalary := 0;
        p_MaxSalary := 0;
        p_BudgetRemaining := 0;
        RETURN;
    END IF;

    -- Compute all statistics
    SELECT
        COUNT(*)::INT,
        COALESCE(SUM(Salary), 0),
        COALESCE(AVG(Salary), 0),
        COALESCE(MIN(Salary), 0),
        COALESCE(MAX(Salary), 0)
    INTO
        p_EmployeeCount,
        p_TotalSalary,
        p_AvgSalary,
        p_MinSalary,
        p_MaxSalary
    FROM public.Employees
    WHERE DepartmentID = p_DepartmentID;

    -- Compute remaining budget
    SELECT BudgetAmount INTO v_Budget 
    FROM public.Departments 
    WHERE DepartmentID = p_DepartmentID;

    p_BudgetRemaining := v_Budget - p_TotalSalary;

END;
$$;

-- =============================================================================
-- PROCEDURE 4: Table-valued parameter procedure
-- Bulk-inserts employees from a TVP with validation
-- =============================================================================

CREATE OR REPLACE PROCEDURE public.sp_BulkInsertEmployees(
    p_Employees public.EmployeeBatchType[],
    INOUT p_InsertedCount INT DEFAULT 0
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_row_count INT;
BEGIN
    p_InsertedCount := 0;

    -- Validate all departments exist
    IF EXISTS (
        SELECT 1 FROM UNNEST(p_Employees) e
        WHERE NOT EXISTS (
            SELECT 1 FROM public.Departments d 
            WHERE d.DepartmentID = e.DepartmentID
        )
    ) THEN
        RAISE EXCEPTION 'One or more department IDs are invalid' USING ERRCODE = '50010';
    END IF;

    -- Validate no duplicate emails against existing data
    IF EXISTS (
        SELECT 1 FROM UNNEST(p_Employees) e
        INNER JOIN public.Employees existing ON existing.Email = e.Email
    ) THEN
        RAISE EXCEPTION 'One or more email addresses already exist' USING ERRCODE = '50011';
    END IF;

    -- Insert from array of composite type
    INSERT INTO public.Employees (FirstName, LastName, Email, DepartmentID, Salary)
    SELECT 
        e.FirstName, 
        e.LastName, 
        e.Email, 
        e.DepartmentID, 
        e.Salary
    FROM UNNEST(p_Employees) e;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    p_InsertedCount := v_row_count;

    -- Log the bulk operation
    INSERT INTO public.AuditLog (TableName, Operation, RecordID, NewValues)
    VALUES ('Employees', 'BULK_INSERT', p_InsertedCount, 'Batch insert via TVP');

    -- Note: PostgreSQL procedures cannot return result sets directly
    -- The inserted count is returned via the INOUT parameter
    -- If a result set is required, consider converting to a FUNCTION
END;
$$;

-- =============================================================================
-- PROCEDURE 1: Cursor-based processing
-- Iterates through employees and applies salary adjustments per department rules
-- =============================================================================

CREATE OR REPLACE FUNCTION public.sp_CursorSalaryAdjustment(
    p_AdjustmentPercent DECIMAL(5,2),
    p_DepartmentID INT DEFAULT NULL
)
RETURNS TABLE(
    EmployeesProcessed INT,
    AdjustmentPercent DECIMAL(5,2)
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_EmpID INT;
    v_CurrentSalary DECIMAL(10,2);
    v_NewSalary DECIMAL(10,2);
    v_EmpDeptID INT;
    v_ProcessedCount INT := 0;
    v_DeptBudget DECIMAL(12,2);
    v_DeptCount INT;
    emp_cursor CURSOR FOR
        SELECT EmployeeID, Salary, DepartmentID
        FROM public.Employees
        WHERE (p_DepartmentID IS NULL OR DepartmentID = p_DepartmentID)
          AND Salary > 0;
BEGIN
    -- Open cursor and iterate through employees
    OPEN emp_cursor;

    LOOP
        FETCH NEXT FROM emp_cursor INTO v_EmpID, v_CurrentSalary, v_EmpDeptID;
        EXIT WHEN NOT FOUND;

        -- Calculate new salary
        v_NewSalary := v_CurrentSalary * (1 + p_AdjustmentPercent / 100.0);

        -- Cap salary at department budget / employee count
        SELECT BudgetAmount INTO v_DeptBudget 
        FROM public.Departments 
        WHERE DepartmentID = v_EmpDeptID;

        SELECT COUNT(*) INTO v_DeptCount 
        FROM public.Employees 
        WHERE DepartmentID = v_EmpDeptID;

        IF v_DeptCount > 0 AND v_NewSalary > (v_DeptBudget / v_DeptCount) THEN
            v_NewSalary := v_DeptBudget / v_DeptCount;
        END IF;

        -- Record history
        INSERT INTO public.SalaryHistory (EmployeeID, OldSalary, NewSalary, Reason)
        VALUES (v_EmpID, v_CurrentSalary, v_NewSalary, 
                'Annual adjustment ' || p_AdjustmentPercent::TEXT || '%');

        -- Apply update
        UPDATE public.Employees 
        SET Salary = v_NewSalary 
        WHERE EmployeeID = v_EmpID;

        v_ProcessedCount := v_ProcessedCount + 1;
    END LOOP;

    CLOSE emp_cursor;

    -- Return result set
    RETURN QUERY SELECT v_ProcessedCount, p_AdjustmentPercent;
END;
$$;

-- Converted from SQL Server procedure: sales.sp_PlaceOrder
-- This procedure performs DML and returns a result set, so it's converted to a FUNCTION
CREATE OR REPLACE FUNCTION sales.sp_PlaceOrder(
    p_CustomerID INT,
    p_ProductID INT,
    p_Quantity INT
)
RETURNS TABLE(
    NewOrderID INT,
    OrderTotal DECIMAL(12,2)
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_UnitPrice DECIMAL(10,2);
    v_Stock INT;
    v_Total DECIMAL(12,2);
    v_OrderID INT;
BEGIN
    -- Read from inventory schema
    SELECT UnitPrice, StockLevel
    INTO v_UnitPrice, v_Stock
    FROM inventory.Products
    WHERE ProductID = p_ProductID;

    -- Check if product exists
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Product not found: %', p_ProductID
            USING ERRCODE = '50001';
    END IF;

    -- Check stock level
    IF v_Stock < p_Quantity THEN
        RAISE EXCEPTION 'Insufficient stock for ProductID %', p_ProductID
            USING ERRCODE = '50001';
    END IF;

    -- Calculate total
    v_Total := v_UnitPrice * p_Quantity;

    -- Begin transaction (implicit in PostgreSQL function, but explicit for clarity)
    -- Insert into sales schema
    INSERT INTO sales.Orders (CustomerID, ProductID, Quantity, OrderTotal, Status)
    VALUES (p_CustomerID, p_ProductID, p_Quantity, v_Total, 'Confirmed')
    RETURNING OrderID INTO v_OrderID;

    -- Write to inventory schema (cross-schema dependency)
    UPDATE inventory.Products
    SET StockLevel = StockLevel - p_Quantity
    WHERE ProductID = p_ProductID;

    -- Insert stock movement record
    INSERT INTO inventory.StockMovements (ProductID, OrderID, QuantityChange, MovementType)
    VALUES (p_ProductID, v_OrderID, -p_Quantity, 'Sale');

    -- Return result set
    RETURN QUERY
    SELECT v_OrderID, v_Total;

EXCEPTION
    WHEN OTHERS THEN
        -- Re-raise the exception (transaction will be rolled back automatically)
        RAISE;
END;
$$;
